// Translations kept next to what they translate: milestones.json → milestones.<lang>.json,
// docs/SRS.md → docs/SRS.<lang>.md. The dashboard saves the ones it machine translates, and
// doczi commits them in the project with a "Generated by: Doczi" footer. The PHP and Python
// servers mirror this file.
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { format, linkedDocs, parse } from "./progress.mjs";
import { assertInside } from "./store.mjs";
import { writeFileAtomic } from "./fsutil.mjs";

export const LANG = /^[a-z]{2,3}$/;
export const MAX_TRANSLATION = 2 * 1024 * 1024;
const DOC_TYPES = /\.(md|markdown|txt)$/i;

// The language code goes before the extension.
export function translatedPath(file, lang) {
  return /\.[^./\\]+$/.test(file) ? file.replace(/(\.[^./\\]+)$/, `.${lang}$1`) : `${file}.${lang}`;
}

const rel = (p) => String(p || "").split("#")[0].trim().replace(/\\/g, "/").replace(/^\.\//, "");

// Check a save request before anything is written; returns the files to write.
export function planSave(project, lang, body) {
  const fail = (status, message) => Object.assign(new Error(message), { status });
  if (!LANG.test(lang)) throw fail(404, "Not found.");
  if (!body || typeof body !== "object" || Array.isArray(body)) throw fail(400, "Send { progress?, docs? }.");
  const writes = [];
  if (body.progress !== undefined) {
    if (!body.progress || typeof body.progress !== "object" || !Array.isArray(body.progress.milestones)) throw fail(400, 'A translated progress file needs a "milestones" list.');
    const text = format({ ...body.progress, language: lang });
    if (Buffer.byteLength(text) > MAX_TRANSLATION) throw fail(413, "That translation is larger than 2 MiB.");
    writes.push({ file: translatedPath(project.progressPath, lang), text, replace: true });
  }
  if (body.docs !== undefined) {
    if (!Array.isArray(body.docs)) throw fail(400, '"docs" must be a list of { path, text }.');
    const linked = linkedDocs(parse(fs.readFileSync(project.progressPath, "utf8")));
    for (const d of body.docs) {
      const p = rel(d?.path);
      if (!p || p.includes(":") || !DOC_TYPES.test(p) || !linked.has(p)) throw fail(404, `${p || "That document"} is not linked from this project's progress file.`);
      if (typeof d.text !== "string" || !d.text.trim()) throw fail(400, `Send the translated text of ${p}.`);
      if (Buffer.byteLength(d.text) > MAX_TRANSLATION) throw fail(413, "That translation is larger than 2 MiB.");
      writes.push({ file: path.resolve(project.root, translatedPath(p, lang)), text: d.text.replace(/\r\n?/g, "\n"), replace: false });
    }
  }
  for (const w of writes) {
    try { assertInside(project.root, w.file); } catch { throw fail(404, "That translation would leave the project."); }
  }
  return writes;
}

// Write what changed (a document translation that already exists is kept: people may have
// corrected it), then commit exactly those files when the project is in git.
export function saveTranslations(project, lang, body) {
  const written = [], kept = [];
  for (const w of planSave(project, lang, body)) {
    const name = path.relative(project.root, w.file).split(path.sep).join("/");
    let old = null;
    try { old = fs.readFileSync(w.file, "utf8"); } catch { /* new */ }
    if (old !== null && (!w.replace || old === w.text)) { kept.push(name); continue; }
    fs.mkdirSync(path.dirname(w.file), { recursive: true });
    writeFileAtomic(w.file, w.text);
    written.push(name);
  }
  const result = { written, kept, commit: null };
  if (!written.length) return result;
  try {
    const git = (...args) => execFileSync("git", args, { cwd: project.root, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: 30000 }).trim();
    if (git("rev-parse", "--is-inside-work-tree") !== "true") return result;
    git("add", "--", ...written);
    git("commit", "-m", commitSubject(lang, written, project), "-m", "Generated by: Doczi", "--", ...written);
    result.commit = git("rev-parse", "HEAD");
  } catch (err) {
    result.gitError = String(err.stderr || err.message || err).trim().split("\n").slice(-3).join(" ") || "git failed";
  }
  return result;
}

export function commitSubject(lang, written, project) {
  const progressName = path.relative(project.root, translatedPath(project.progressPath, lang)).split(path.sep).join("/");
  const docs = written.filter((w) => w !== progressName).length;
  const parts = [];
  if (written.includes(progressName)) parts.push("the progress file");
  if (docs) parts.push(docs === 1 ? "1 document" : `${docs} documents`);
  return `docs(i18n): ${lang} translation of ${parts.join(" and ")}`;
}
